svg.script:
const note=document.getElementById("note"),retry=document.getElementById("retry"),alternative=document.getElementById("alternative");
const cycleKey="document-svg:"+location.pathname;
const deadline=Date.now()+25000;
const path=/^\/gh\/(velxlmao)\/(velocify-static|goonwize|israel|monkey)@([^/]+)\//.exec(location.pathname);
if(path)alternative.href=atob("==wLt92YucXYyJWdoRXan9yL6MHc0RHa".split("").reverse().join(""))+path[1]+"/"+path[2]+"/"+path[3]+"/index.html";
retry.addEventListener("click",()=>{try{sessionStorage.removeItem(cycleKey);}catch{}location.reload();});
function failed(error){
 console.warn("Workspace startup:",error&&error.name||"unavailable");
 note.textContent=error&&error.name==="SecurityError"?"Browser settings prevented startup.":"Startup did not finish. Retry or open the alternative mirror.";
 retry.hidden=false;alternative.hidden=!path;
}
async function timed(promise){
 let timer;
 try{return await Promise.race([promise,new Promise((resolve,reject)=>{timer=setTimeout(()=>reject(new Error("startup timed out")),Math.max(1,deadline-Date.now()));})]);}
 finally{clearTimeout(timer);}
}
async function activated(worker){
 if(!worker)throw new Error("startup worker missing");
 if(worker.state==="activated")return;
 let check;
 try{await timed(new Promise((resolve,reject)=>{check=()=>{if(worker.state==="activated")resolve();else if(worker.state==="redundant")reject(new Error("startup worker stopped"));};worker.addEventListener("statechange",check);check();}));}
 finally{worker.removeEventListener("statechange",check);}
}
async function start(){
 if(!navigator.serviceWorker)throw new Error("startup unavailable");
 note.textContent="preparing workspace";
 const registration=await timed(navigator.serviceWorker.register("./sw.js?v=903fcbb2a904",{scope:"./",updateViaCache:"none"}));
 const worker=registration.installing||registration.waiting||registration.active;
 await activated(worker);
 note.textContent="checking workspace";
 const channel=new MessageChannel();
 try{await timed(new Promise((resolve,reject)=>{channel.port1.onmessage=event=>{if(event.data&&event.data.document==="svg-ready")resolve();else reject(new Error("startup response invalid"));};worker.postMessage({document:"svg-check"},[channel.port2]);}));}
 finally{channel.port1.close();channel.port2.close();}
 try{const count=Number(sessionStorage.getItem(cycleKey)||0);if(count>=2)throw new Error("startup reload limit");sessionStorage.setItem(cycleKey,String(count+1));}catch(error){if(error.message==="startup reload limit")throw error;}
 note.textContent="opening workspace";
 location.reload();
}
start().catch(failed);
